HTML_CONTENT = '<!DOCTYPE html>\n<html lang="es-AR">\n<head>\n<meta charset="UTF-8" />\n<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />\n<title>DS Compras</title>\n<link rel="icon" href="data:image/jpeg;base64," />\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&family=IBM+Plex+Sans:wght@400;500;600&display=swap" rel="stylesheet">\n<style>\n  :root {\n    --paper: #F4F0E4;\n    --paper-dark: #E9E4D4;\n    --ink: #14202E;\n    --ink-soft: #56636F;\n    --navy: #16324F;\n    --navy-deep: #0E2138;\n    --gold: #B4894A;\n    --gold-soft: #E4D3A8;\n    --verified: #2F6F4E;\n    --verified-bg: #E4EFE8;\n    --warning: #96700A;\n    --warning-bg: #F3E8CC;\n    --danger: #9C3D2E;\n    --accent: var(--navy);\n    --line: #CBC2A8;\n    --radius: 2px;\n  }\n\n  * { box-sizing: border-box; }\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    background: var(--paper-dark);\n    color: var(--ink);\n    font-family: \'IBM Plex Sans\', sans-serif;\n    -webkit-font-smoothing: antialiased;\n  }\n\n  body {\n    min-height: 100vh;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n  }\n\n  header {\n    width: 100%;\n    max-width: 480px;\n    padding: 20px 16px 10px;\n    text-align: center;\n  }\n\n  header img.logo {\n    width: 84px;\n    height: auto;\n    display: block;\n    margin: 0 auto 6px;\n  }\n\n  header .brand {\n    font-family: \'IBM Plex Mono\', monospace;\n    font-weight: 700;\n    font-size: 15px;\n    letter-spacing: 0.12em;\n    text-transform: uppercase;\n    color: var(--navy-deep);\n  }\n\n  header .brand span { color: var(--gold); }\n\n  header .sub {\n    margin-top: 4px;\n    font-size: 11.5px;\n    color: var(--ink-soft);\n    font-family: \'IBM Plex Mono\', monospace;\n    letter-spacing: 0.04em;\n  }\n\n  #feed {\n    width: 100%;\n    max-width: 480px;\n    flex: 1;\n    overflow-y: auto;\n    padding: 4px 12px 140px;\n    display: flex;\n    flex-direction: column;\n    gap: 14px;\n  }\n\n  .msg-user {\n    align-self: flex-end;\n    max-width: 82%;\n    background: var(--navy-deep);\n    color: var(--paper);\n    padding: 10px 14px;\n    border-radius: var(--radius);\n    font-size: 14px;\n    line-height: 1.4;\n  }\n\n  .msg-agent-text {\n    align-self: flex-start;\n    max-width: 90%;\n    font-size: 14px;\n    line-height: 1.45;\n    padding: 2px 4px;\n  }\n\n  /* --- El ticket: elemento de firma de la marca --- */\n  .ticket {\n    background: var(--paper);\n    border: 1px solid var(--line);\n    position: relative;\n    padding: 14px 16px 12px;\n    font-family: \'IBM Plex Mono\', monospace;\n  }\n\n  .ticket::before, .ticket::after {\n    content: "";\n    position: absolute;\n    left: 0; right: 0;\n    height: 8px;\n    background:\n      radial-gradient(circle 5px at 8px 0, transparent 4px, var(--paper-dark) 5px) repeat-x;\n    background-size: 16px 16px;\n  }\n  .ticket::before { top: -1px; transform: rotate(180deg); background-position: 8px -4px;}\n  .ticket::after { bottom: -1px; }\n\n  .ticket-rank {\n    font-size: 11px;\n    color: var(--ink-soft);\n    letter-spacing: 0.08em;\n  }\n\n  .ticket-label {\n    display: inline-block;\n    margin-top: 4px;\n    transform: rotate(-2deg);\n    border: 1.5px solid var(--gold);\n    color: #8A6A2E;\n    background: var(--gold-soft);\n    font-weight: 700;\n    font-size: 11px;\n    letter-spacing: 0.08em;\n    text-transform: uppercase;\n    padding: 2px 8px;\n  }\n\n  .ticket-modelo {\n    margin-top: 10px;\n    font-size: 14px;\n    font-weight: 600;\n    color: var(--ink);\n    line-height: 1.3;\n  }\n\n  .ticket-seller {\n    font-size: 11px;\n    color: var(--ink-soft);\n    margin-top: 2px;\n  }\n\n  .ticket-divider {\n    border: none;\n    border-top: 1px dashed var(--line);\n    margin: 10px 0;\n  }\n\n  .ticket-row {\n    display: flex;\n    justify-content: space-between;\n    font-size: 12.5px;\n    padding: 2px 0;\n  }\n\n  .ticket-row .k { color: var(--ink-soft); }\n  .ticket-row .v { text-align: right; font-weight: 500; }\n\n  .ticket-total {\n    display: flex;\n    justify-content: space-between;\n    margin-top: 10px;\n    padding-top: 8px;\n    border-top: 1px solid var(--navy-deep);\n    font-size: 15px;\n    font-weight: 700;\n    color: var(--navy-deep);\n  }\n\n  .ticket-precio-pub {\n    text-decoration: line-through;\n    color: var(--ink-soft);\n    font-weight: 400;\n    font-size: 12px;\n  }\n\n  .tag {\n    display: inline-block;\n    font-size: 10.5px;\n    padding: 1px 6px;\n    border-radius: var(--radius);\n    margin-top: 6px;\n    margin-right: 4px;\n  }\n  .tag-warn { background: var(--warning-bg); color: var(--warning); }\n\n  .buy-wait {\n    align-self: stretch;\n    background: var(--verified-bg);\n    border-left: 3px solid var(--verified);\n    padding: 10px 12px;\n    font-size: 13px;\n    line-height: 1.4;\n  }\n  .buy-wait.esperar { background: var(--warning-bg); border-left-color: var(--warning); }\n  .buy-wait.neutro { background: #EDEBE0; border-left-color: var(--ink-soft); }\n\n  #composer {\n    position: fixed;\n    bottom: 0;\n    left: 0; right: 0;\n    display: flex;\n    justify-content: center;\n    background: linear-gradient(to top, var(--paper-dark) 60%, transparent);\n    padding: 16px 12px calc(16px + env(safe-area-inset-bottom));\n  }\n\n  #composer form {\n    width: 100%;\n    max-width: 480px;\n    display: flex;\n    gap: 8px;\n  }\n\n  #composer input {\n    flex: 1;\n    border: 1.5px solid var(--navy-deep);\n    border-radius: var(--radius);\n    padding: 12px 14px;\n    font-size: 15px;\n    font-family: \'IBM Plex Sans\', sans-serif;\n    background: var(--paper);\n    color: var(--ink);\n  }\n  #composer input:focus { outline: 2px solid var(--gold); outline-offset: 1px; }\n\n  #composer button {\n    border: none;\n    background: var(--navy-deep);\n    color: var(--gold-soft);\n    padding: 0 18px;\n    border-radius: var(--radius);\n    font-weight: 600;\n    font-size: 14px;\n    cursor: pointer;\n  }\n  #composer button:active { background: var(--navy); }\n  #composer button:disabled { opacity: 0.5; }\n\n  .typing { font-family: \'IBM Plex Mono\', monospace; font-size: 12px; color: var(--ink-soft); }\n\n  .debug-line {\n    align-self: flex-start;\n    font-family: \'IBM Plex Mono\', monospace;\n    font-size: 10.5px;\n    color: var(--ink-soft);\n    background: var(--paper);\n    border: 1px dashed var(--line);\n    padding: 4px 8px;\n    max-width: 90%;\n  }\n\n  @media (prefers-reduced-motion: no-preference) {\n    .ticket { animation: rise 0.25s ease-out; }\n    @keyframes rise { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }\n  }\n</style>\n</head>\n<body>\n  <header>\n    <img class="logo" src="data:image/jpeg;base64," alt="DS Compras" />\n    <div class="brand">DS <span>Compras</span></div>\n    <div class="sub">tu agente inteligente</div>\n  </header>\n\n  <div id="feed"></div>\n\n  <div id="composer">\n    <form id="form">\n      <input id="input" type="text" placeholder="Ej: busco un aire acondicionado" autocomplete="off" />\n      <button type="submit">Enviar</button>\n    </form>\n  </div>\n\n<script>\nconst feed = document.getElementById(\'feed\');\nconst form = document.getElementById(\'form\');\nconst input = document.getElementById(\'input\');\nconst sessionId = \'web-\' + Math.random().toString(36).slice(2);\n\nfunction addUserMessage(text) {\n  const el = document.createElement(\'div\');\n  el.className = \'msg-user\';\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addAgentText(text) {\n  const el = document.createElement(\'div\');\n  el.className = \'msg-agent-text\';\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addTicket(card) {\n  const el = document.createElement(\'div\');\n  el.className = \'ticket\';\n  const warnHtml = (card.warnings || []).map(w => `<span class="tag tag-warn">⚠ ${w}</span>`).join(\'\');\n  el.innerHTML = `\n    <div class="ticket-rank">#${card.rank}${card.empatado ? \' · EMPATADO\' : \'\'}</div>\n    ${card.label ? `<div class="ticket-label">${card.label}</div>` : \'\'}\n    <div class="ticket-modelo">${card.modelo}</div>\n    <div class="ticket-seller">${card.seller}</div>\n    <hr class="ticket-divider" />\n    <div class="ticket-row"><span class="k">Calificación</span><span class="v">${card.calificacion_texto}</span></div>\n    <div class="ticket-row"><span class="k">Financiación</span><span class="v">${card.cuotas_texto}</span></div>\n    <div class="ticket-row"><span class="k">Promoción</span><span class="v">${card.promocion_texto}</span></div>\n    <div class="ticket-row"><span class="k">Envío</span><span class="v">${card.envio_texto}</span></div>\n    <div class="ticket-total">\n      <span class="ticket-precio-pub">${card.precio_publicado}</span>\n      <span>${card.costo_efectivo}</span>\n    </div>\n    ${warnHtml}\n  `;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addBuyWait(text, recommendation) {\n  const el = document.createElement(\'div\');\n  const cls = recommendation && recommendation.includes(\'esperar\') ? \'esperar\'\n            : recommendation && recommendation.includes(\'neutro\') ? \'neutro\' : \'\';\n  el.className = \'buy-wait \' + cls;\n  el.textContent = text;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nfunction addDebugLine(intent, entities, router, memoria) {\n  const el = document.createElement(\'div\');\n  el.className = \'debug-line\';\n  const ents = Object.entries(entities || {}).map(([k, v]) => `${k}=${v}`).join(\', \') || \'(ninguna)\';\n  const routerCorto = router === \'LLMIntentRouter\' ? \'IA (Claude)\' : \'reglas fijas\';\n  const memoriaCorta = memoria === \'PostgresMemoryStore\' ? \'Postgres (persiste)\' : \'en proceso (no persiste)\';\n  el.textContent = `🔧 buscador=${routerCorto} · memoria=${memoriaCorta} · intent=${intent} · entidades: ${ents}`;\n  feed.appendChild(el);\n  feed.scrollTop = feed.scrollHeight;\n}\n\nasync function sendMessage(message) {\n  addUserMessage(message);\n  input.value = \'\';\n  input.disabled = true;\n\n  const typing = document.createElement(\'div\');\n  typing.className = \'typing\';\n  typing.textContent = \'buscando…\';\n  feed.appendChild(typing);\n  feed.scrollTop = feed.scrollHeight;\n\n  try {\n    const res = await fetch(\'/v1/chat\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ message, user_id: \'demo-user\', session_id: sessionId }),\n    });\n    const data = await res.json();\n    typing.remove();\n\n    if (data.debug_intent) addDebugLine(data.debug_intent, data.debug_entities, data.debug_router, data.debug_memory);\n    if (data.message) addAgentText(data.message);\n    (data.cards || []).forEach(addTicket);\n    if (data.buy_wait_text) {\n      addBuyWait(data.buy_wait_text, data.buy_wait_text.toLowerCase());\n    }\n  } catch (err) {\n    typing.remove();\n    addAgentText(\'Hubo un error de conexión. Probá de nuevo en un momento.\');\n  } finally {\n    input.disabled = false;\n    input.focus();\n  }\n}\n\nform.addEventListener(\'submit\', (e) => {\n  e.preventDefault();\n  const value = input.value.trim();\n  if (value) sendMessage(value);\n});\n\naddAgentText(\'Hola, soy DS Compras. Contame qué estás buscando (ej: "busco un aire acondicionado, tengo Nativa Mastercard").\');\n</script>\n</body>\n</html>\n'
